+
+import java.util.*;
+import javax.script.*;
+import org.openjdk.engine.python.AbstractPythonScriptEngine.PyExecMode;
+import org.openjdk.engine.python.*;
+
+void main() throws Exception {
+    var m = new ScriptEngineManager();
+    var e = (PythonScriptEngine) m.getEngineByName("python");
+
+    var re = (PythonRemoteScriptEngine) PythonRemoteScriptEngine.create(e);
+    long processId = re.getRemotePid();
+
+    // kill remote runaway process
+    Timer timer = new Timer();
+    timer.schedule(new TimerTask() {
+        @Override
+        public void run() {
+            try {
+                ProcessHandle.of(processId).ifPresent(p -> p.destroy());
+            } catch (Exception ex) {
+                ex.printStackTrace();
+            }
+            timer.cancel();
+        }
+    }, 2000);
+
+    re.setExecMode(PyExecMode.FILE);
+    try {
+        re.eval("""
+        while True:
+            print("hello")
+        """);
+    } catch (ScriptException se) {
+        IO.println(se);
+    }
+    IO.println("Goodbye!");
+}

